1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AgeBand;
13	import org.springframework.samples.petclinic.util.CustomerCode;
14	import org.springframework.samples.petclinic.util.Luhn;
15	import org.springframework.samples.petclinic.util.OwnerRegion;
16	
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
27	    @Mapping(target = "initials", expression = "java(initials(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
37	    default String displayName(Owner owner) {
38	        return owner.getLastName() + ", " + owner.getFirstName();
39	    }
40	
41	    /** The upper-cased first letters of firstName and lastName, dot-separated with a
42	     *  trailing dot, e.g. 'J.S.'. */
43	    default String initials(Owner owner) {
44	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
45	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
46	    }
47	
48	    /** The membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
49	     *  the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Null when either source field is absent. */
50	    default String membershipNumber(Owner owner) {
51	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
55	    }
56	
57	    /** The Luhn check digit over the digits of the customerCode. Null when the customerCode
58	     *  is absent. */
59	    default Integer checkDigit(Owner owner) {
60	        return owner.getCustomerCode() == null ? null : Luhn.checkDigit(owner.getCustomerCode());
61	    }
62	
63	    /** The owner's locality: the REGION segment of its customerCode, which is the canonical region
64	     *  the code was built from. Falls back to deriving the region straight from the postcode and
65	     *  city when the customerCode is absent (so an owner without one still resolves a locality). */
66	    default String locality(Owner owner) {
67	        return owner.getCustomerCode() != null
68	                ? CustomerCode.region(owner.getCustomerCode())
69	                : OwnerRegion.of(owner.getPostcode(), owner.getCity());
70	    }
71	
72	    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
73	     *  otherwise 'PHONE'. */
74	    default String contactPreference(Owner owner) {
75	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
76	    }
77	
78	    /** The owner's derived duplicate-detection identity key: normalized telephone, email and
79	     *  household id joined by '|'. See {@link OwnerIdentity#key}. */
80	    default String identityKey(Owner owner) {
81	        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
82	    }
83	
84	    /** The owner's age band derived from its birthDate against its registrationDate, or null when
85	     *  either date is absent. See {@link AgeBand}. */
86	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
87	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
88	            return null;
89	        }
90	        return OwnerDto.AgeBandEnum.fromValue(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()));
91	    }
92	
93	    Owner toOwner(OwnerDto ownerDto);
94	
95	    @Mapping(target = "id", ignore = true)
96	    @Mapping(target = "pets", ignore = true)
97	    Owner toOwner(OwnerFieldsDto ownerDto);
98	
99	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
100	
101	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
102	
103	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
104	        OwnerPageDto ownerPageDto = new OwnerPageDto();
105	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
106	        ownerPageDto.setPage(ownerPage.getNumber());
107	        ownerPageDto.setSize(ownerPage.getSize());
108	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
109	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
110	        return ownerPageDto;
111	    }
112	}
