1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Out;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerFieldsException;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * First step of the create/update owner pipelines. Normalizes the telephone to canonical
12	 * E.164 form and writes it back onto the body, so the persisted and returned
13	 * {@code telephone} is that E.164 string. A telephone that cannot form a valid E.164 number
14	 * throws {@link InvalidOwnerFieldsException} for a 400. Because it must run before the DTO's
15	 * pattern check would reject the raw input, this is the pipeline's sole {@code @RequestBody}
16	 * binding; the normalized body is published for {@link ValidateOwnerFields}.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized)
21	            throws InvalidOwnerFieldsException {
22	
23	        String e164 = OwnerTelephone.toE164(request.getTelephone())
24	                .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
25	
26	        request.setTelephone(e164);
27	        normalized.set(request);
28	    }
29	}
