3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** telephone-display: 'telephoneDisplay' is the stored E.164 number formatted for humans
8	 * (country code, space, national digits grouped in threes); raw 'telephone' stays E.164. A fixed
9	 * input gives an exact expected display. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreFormatsTelephoneDisplay() throws Exception {
14			ObjectNode o = ownerNode();
15			o.put("telephone", "0412 345 678");
16			int id = createOwnerOk(o);
17			getOwner(id).andExpect(jsonPath("$.telephone").value("+61412345678"))
18					.andExpect(jsonPath("$.telephoneDisplay").value("+61 412 345 678"));
19		}
20	}
